import React, { useState } from 'react';
import { Trash2, Plus, Users, Play, Clock, Layers, Globe, Calendar } from 'lucide-react';

const distributeSubjects = (subjectList, daysCount) => {
  const sorted = [...subjectList].sort((a, b) => a.code.localeCompare(b.code));
  const result = Array.from({ length: daysCount }, () => []);
  sorted.forEach((subject, index) => {
    result[index % daysCount].push(subject);
  });
  return result;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']);
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("12:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1);
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // Proctor Window State
  const [pName, setPName] = useState("");
  const [pStart, setPStart] = useState("");
  const [pEnd, setPEnd] = useState("");
  const [roomNum, setRoomNum] = useState("");

  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const addProctor = () => {
    if (!pName || !pStart || !pEnd) return alert("Fill Name and Availability Window!");
    const updated = [...proctors, { id: Date.now(), name: pName.toUpperCase(), start: pStart, end: pEnd }];
    onUpdate('proctors', updated);
    setPName("");
  };

  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert("No subjects added!");
    if (examDates.some(d => !d)) return alert("Missing exam dates!");

    const dailySplit = distributeSubjects(yearSubjects, examDays);
    const finalGeneratedData = [];

    for (let dayIdx = 0; dayIdx < dailySplit.length; dayIdx++) {
      const daySubjects = dailySplit[dayIdx];
      const currentDate = examDates[dayIdx];

      // 1. ROOM ALLOCATION (Consecutive Logic + Global Fallback)
      let availableRooms = rooms.filter(r => !globalSchedule.some(as => as.room === r.number && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)));

      if (roomSource === "Global" || availableRooms.length < sectionCount) {
        const globals = allDepartments.flatMap(d => d.rooms).filter(r => r.type === "Global" && !globalSchedule.some(as => as.room === r.number && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)));
        availableRooms = [...new Set([...availableRooms, ...globals])];
      }
      availableRooms.sort((a, b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

      let chosenRoomNumbers = [];
      for (let i = 0; i <= availableRooms.length - sectionCount; i++) {
        const slice = availableRooms.slice(i, i + sectionCount);
        const isConsec = slice.every((r, idx) => idx === 0 || parseInt(r.number) === parseInt(slice[idx - 1].number) + 1);
        if (isConsec) { chosenRoomNumbers = slice.map(r => r.number); break; }
      }
      if (chosenRoomNumbers.length === 0) chosenRoomNumbers = availableRooms.slice(0, sectionCount).map(r => r.number);
      if (chosenRoomNumbers.length < sectionCount) return alert(`Insufficient Rooms on Day ${dayIdx+1}`);

      // 2. SECTION LOOP (Constraint: Same time, same day)
      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;

        // Find Proctor (Availability Check)
        let proctor = proctors.find(p => currentDate >= p.start && currentDate <= p.end && !globalSchedule.some(as => as.proctor === p.name && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)));

        if (!proctor || proctorSource === "Global") {
            proctor = allDepartments.flatMap(d => d.proctors).find(p => currentDate >= p.start && currentDate <= p.end && !globalSchedule.some(as => as.proctor === p.name && as.exam_date === currentDate && (startTime < as.end_time && endTime > as.start_time)));
        }

        daySubjects.forEach(sub => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID,
            year_level: selectedYear, dept_code: deptCode, exam_date: currentDate,
            start_time: startTime, end_time: endTime, room: chosenRoomNumbers[s],
            proctor: proctor?.name || "RESERVE STAFF"
          });
        });
      }
    }
    onGenerate(finalGeneratedData, examDates);
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden">
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <div className="flex items-center gap-3"><Layers className="text-blue-500" /><h2 className="text-3xl font-black uppercase tracking-tighter">{deptName}</h2></div>
      </div>

      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-md text-blue-600' : 'text-slate-400'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-8 min-h-[500px]">
        {activeTab === 'proctors' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-emerald-50 p-6 rounded-3xl">
              <input value={pName} onChange={e=>setPName(e.target.value)} placeholder="NAME" className="p-3 rounded-xl text-xs font-bold" />
              <div><label className="text-[8px] font-black text-emerald-600 block uppercase">Start Avail</label><input type="date" value={pStart} onChange={e=>setPStart(e.target.value)} className="w-full p-2 rounded-lg text-xs" /></div>
              <div><label className="text-[8px] font-black text-emerald-600 block uppercase">End Avail</label><input type="date" value={pEnd} onChange={e=>setPEnd(e.target.value)} className="w-full p-2 rounded-lg text-xs" /></div>
              <button onClick={addProctor} className="bg-emerald-600 text-white rounded-xl font-black text-[10px] uppercase">Add Proctor</button>
            </div>
            {proctors.map(p => (
              <div key={p.id} className="flex justify-between p-4 border rounded-2xl bg-white shadow-sm">
                <span className="font-black text-xs">{p.name} <span className="text-slate-400 ml-2">({p.start} to {p.end})</span></span>
                <button onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))}><Trash2 size={16} className="text-slate-200 hover:text-red-500"/></button>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white space-y-8">
            <div className="grid grid-cols-2 gap-10">
              <div className="space-y-6">
                <div><label className="text-[10px] font-black text-blue-400 uppercase block mb-2 tracking-[0.2em]">How many exam days?</label><input type="number" value={examDays} onChange={e=>handleExamDayChange(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl text-xl font-black" /></div>
                <div className="space-y-2"><label className="text-[10px] font-black text-blue-400 uppercase block mb-1">Exact Dates</label>{examDates.map((d, i) => (<input key={i} type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="w-full bg-slate-800 p-3 rounded-xl text-xs font-bold" />))}</div>
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Time Start</label><input type="time" value={startTime} onChange={e=>setStartTime(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl font-black" /></div>
                  <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Time End</label><input type="time" value={endTime} onChange={e=>setEndTime(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl font-black" /></div>
                </div>
              </div>
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="text-[10px] font-black text-emerald-400 uppercase block mb-1">Year Level</label><select value={selectedYear} onChange={e=>setSelectedYear(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl font-black">{[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}</select></div>
                  <div><label className="text-[10px] font-black text-emerald-400 uppercase block mb-1">Sections</label><input type="number" value={sectionCount} onChange={e=>setSectionCount(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl font-black" /></div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Proctors</label><select value={proctorSource} onChange={e=>setProctorSource(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl text-[10px] font-black"><option>Department</option><option>Global</option></select></div>
                  <div><label className="text-[10px] font-black text-slate-500 uppercase block mb-1">Rooms</label><select value={roomSource} onChange={e=>setRoomSource(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl text-[10px] font-black"><option>Department</option><option>Global</option></select></div>
                </div>
                <button onClick={handleGenerateClick} className="w-full bg-blue-600 hover:bg-blue-500 py-8 rounded-[2.5rem] font-black uppercase tracking-[0.4em] flex items-center justify-center gap-4 transition-all active:scale-95 shadow-2xl shadow-blue-900/40"><Play size={24} fill="currentColor" /> Generate Schedule</button>
              </div>
            </div>
          </div>
        )}

        {/* Subjects Tab */}
        {activeTab === 'subjects' && (
          <div className="space-y-4">
            <div className="grid grid-cols-4 gap-2 bg-slate-50 p-4 rounded-2xl">
              <select className="p-2 rounded-lg text-xs font-bold" onChange={(e) => setSelectedYear(e.target.value)}>{[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}</select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-2 rounded-lg text-xs font-bold" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-2 rounded-lg text-xs font-bold" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value; const n = document.getElementById(`sN-${deptId}`).value;
                if(c && n) {
                    const updated = { ...subjects, [selectedYear]: [...subjects[selectedYear], { code: c.toUpperCase(), name: n }] };
                    onUpdate('subjects', updated);
                    document.getElementById(`sC-${deptId}`).value = ''; document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-lg"><Plus /></button>
            </div>
            <div className="grid grid-cols-2 gap-2">{subjects[selectedYear].map((s, i) => (<div key={i} className="flex justify-between p-3 bg-white border rounded-xl items-center"><span className="text-xs font-bold">{s.code}</span><button onClick={() => onUpdate('subjects', {...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i)}) }><Trash2 size={14} className="text-slate-200 hover:text-red-500" /></button></div>))}</div>
          </div>
        )}

        {/* Rooms Tab */}
        {activeTab === 'rooms' && (
          <div className="space-y-4">
            <div className="flex gap-2">
                <input value={roomNum} onChange={e=>setRoomNum(e.target.value)} placeholder="ROOM #" className="flex-1 p-3 border rounded-xl text-xs font-bold" />
                <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Department'}]); setRoomNum(""); } }} className="bg-amber-600 text-white px-4 rounded-xl text-[10px] font-black uppercase">Dept</button>
                <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Global'}]); setRoomNum(""); } }} className="bg-slate-800 text-white px-4 rounded-xl text-[10px] font-black uppercase">Global</button>
            </div>
            <div className="grid grid-cols-4 gap-2">{rooms.map(r => (<div key={r.id} className="p-4 bg-slate-50 rounded-xl text-center relative group"><span className="font-black text-lg">{r.number}</span><span className="block text-[8px] uppercase font-black text-slate-400">{r.type}</span><button className="absolute top-1 right-1 opacity-0 group-hover:opacity-100" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={12}/></button></div>))}</div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
